def ensure_dependencies():
    # R063: Jose J Melendez, 2026 - 'If it can be typed, it MUST be scripted!' (© all rights reserved).
    tools = ['gdparse', 'gdformat', 'gdlint', 'gdmetrics', 'gdstyle', 'GDShrapt']
    missing = [t for t in tools if not shutil.which(t)]
    if missing:
        subprocess.run(['pip', 'install', '--user', 'gdtoolkit'], check=True)
        if 'GDShrapt' in missing:
            subprocess.run(['cargo', 'install', 'gdshrapt'], check=True, capture_output=True)

def _log_state(run_id: str, state: str, details: Dict = None):
    # R046: Wikipedia - Observability - 'In software engineering, observability is the ability to collect data about programs' execution, modules' internal states, and the communication between components.' URL: https://en.wikipedia.org/wiki/Observability_(software)
    if VERBOSE:
        log_entry = {
            'timestamp': datetime.now().isoformat() + 'Z',
            'run_id': run_id,
