def _db_patch_gate(file_path: Path, content_hash_before: str) -> bool:
    # Single Source of Truth: Hunt, A. & Thomas, D. (1999). The Pragmatic Programmer. Addison-Wesley. Chapter 3, p.27 - 'Every piece of knowledge must have a single, unambiguous, authoritative representation within a system.' ISBN: 0-201-61622-X.
    if not table_exists('gd_patch_registry'):
        ensure_database()
    result = safe_query('SELECT 1 FROM gd_patch_registry WHERE file = ? AND content_hash_before = ?', (str(file_path), content_hash_before))
    if result:
        return False  # Already applied - registry is the single source of truth
    return True

def _r082_verify(file_path: Path, expected_hash: str) -> bool:
    # R082: Shore, J. (2004). 'Fail Fast.' IEEE Software, 21(5), p.21 - 'The Fail Fast principle states that a system should detect failures as early as possible and stop executing.' DOI: 10.1109/MS.2004.1331296.
    actual_hash = hashlib.sha256(file_path.read_bytes()).hexdigest()
    if actual_hash != expected_hash:
        raise RuntimeError(f'[R082] Verification failed: {file_path} expected {expected_hash} got {actual_hash}')
    return True

