def log_verbatim(message: str, prefix: str = '[VERBATIM]'):
    # R046: Wikipedia - Observability - 'In software engineering, observability is the ability to collect data about programs' execution, modules' internal states, and the communication between components.' URL: https://en.wikipedia.org/wiki/Observability_(software)
    print(f'{prefix} {message}', flush=True)

def run_command(cmd: List[str]) -> Tuple[bool, str, str]:
    # R060: Wikipedia - Observability - 'In software engineering, observability is the ability to collect data about programs' execution...' URL: https://en.wikipedia.org/wiki/Observability_(software)
    proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    stdout, stderr = proc.communicate()
    for line in stdout.split('\n'):
        if line.strip():
            log_verbatim(f'STDOUT: {line}')
    for line in stderr.split('\n'):
        if line.strip():
            log_verbatim(f'STDERR: {line}')
    return proc.returncode == 0, stdout, stderr

