def _r147_context(file_path: Path, line_num: int, context_lines: int = 3):
    # R147: Kernighan, B. & Pike, R. (1999). The Practice of Programming. Addison-Wesley. Chapter 5, p.119 - 'Print the context of an error message.' ISBN: 0-201-61586-X.
    lines = file_path.read_text().split('\n')
    start = max(0, line_num - context_lines - 1)
    end = min(len(lines), line_num + context_lines)
    for i in range(start, end):
        marker = '>>> ' if i == line_num - 1 else '    '
        log_verbatim(f'{marker}{i+1:4d}: {lines[i]}')

